@RunWith(AndroidJUnit4::class)
class UserDaoTest {

    private lateinit var db: AppDatabase

    @Before fun setUp() {
        db = Room.inMemoryDatabaseBuilder(context, AppDatabase::class.java)
            .build()
    }

    @After fun tearDown() { db.close() }

    @Test
    fun `insert then find returns the user`() = runTest {
        db.userDao().insert(User(id = 1, name = "Ada"))

        assertEquals("Ada", db.userDao().find(1)?.name)
