@RunWith(AndroidJUnit4::class)
class UserMigrationTest {

    private val helper = MigrationTestHelper(
        InstrumentationRegistry.getInstrumentation(),
        AppDatabase::class.java
    )

    @Test
    fun `migrate 1 to 2 keeps user rows`() {
        helper.createDatabase(TEST_DB, 1).use { db ->
            db.execSQL("INSERT INTO users (id, name) VALUES (1, 'Ada')")
        }

        helper.runMigrationsAndValidate(TEST_DB, 2, true, MIGRATION_1_2)

        val room = Room.databaseBuilder(context, AppDatabase::class.java, TEST_DB).build()
        val cursor = room.openHelper.writableDatabase.query("SELECT name FROM users WHERE id = 1")
        cursor.use { c -> c.moveToFirst(); assertEquals("Ada", c.getString(0)) }
        room.close()
    }
}

@RunWith(AndroidJUnit4::class)
class SyncWorkerTest {

    private lateinit var driver: TestDriver

    @Before fun init() {
        val config = Configuration.Builder().setMinimumLoggingLevel(Log.DEBUG).build()
        WorkManagerTestInitHelper.initializeTestWorkManager(context, config)
        driver = WorkManagerTestInitHelper.getTestDriver(context)!!
    }

    @Test
    fun `worker succeeds when upload is healthy`() = runTest {
        val worker = TestListenableWorkerBuilder<SyncWorker>(context)
            .setInputData(workDataOf("url" to "https://api.example.com/sync"))
            .build()

        assertEquals(Result.success(), worker.doWork())
    }

    @Test
    fun `constraint gates the run until conditions are met`() {
        val request = OneTimeWorkRequestBuilder<SyncWorker>()
            .setConstraints(Constraints.Builder().setRequiresBatteryNotLow(true).build())
            .build()

        WorkManager.getInstance(context).enqueue(request)
        driver.setAllConstraintsMet(request.id)

        val info = WorkManager.getInstance(context).getWorkInfoById(request.id).get()
        assertEquals(WorkInfo.State.SUCCEEDED, info.state)
    }
}

class GitHubApiTest {

    private lateinit var server: MockWebServer
    private lateinit var api: GitHubApi

    @Before fun setUp() {
        server = MockWebServer().apply { start() }
        api = Retrofit.Builder()
            .baseUrl(server.url("/"))
            .addConverterFactory(MoshiConverterFactory.create())
            .build()
            .create(GitHubApi::class.java)
    }

    @After fun tearDown() { server.shutdown() }

    @Test
    fun `sends the path parameter as expected`() = runTest {
        server.enqueue(MockResponse().setBody("""{"id":42,"name":"okhttp"}"""))

        val repo = api.getRepo("square", "okhttp")

        val request = server.takeRequest()
        assertEquals("/repos/square/okhttp", request.path)
        assertEquals("GET", request.method)
    }

    @Test
    fun `maps http 500 to our error type`() = runTest {
        server.enqueue(MockResponse().setResponseCode(500).setBody("""{"message":"boom"}"""))

        val error = assertFailsWith<ApiException> { api.getRepo("square", "okhttp") }
        assertEquals(500, error.code)
    }
}

