class CountingIdlingResource : IdlingResource {
    private val waiters = AtomicInteger(0)
    private var callback: IdlingResource.ResourceCallback? = null

    override fun getName() = "background-work"
    override fun isIdleNow() = waiters.get() == 0
    override fun registerIdleTransitionCallback(cb: IdlingResource.ResourceCallback?) { callback = cb }

    fun startWork() { waiters.incrementAndGet() }
    fun finishWork() { if (waiters.decrementAndGet() == 0) callback?.onTransitionToIdle() }
}

