    private val device = UiDevice.getInstance(InstrumentationRegistry.getInstrumentation())

    @Before fun setUp() {
        device.executeShellCommand("settings put global window_animation_scale 0")
        device.executeShellCommand("settings put global transition_animation_scale 0")
        device.executeShellCommand("settings put global animator_duration_scale 0")
        device.pressHome()
    }

    @After fun tearDown() {
        device.takeScreenshot(File("build/reports/e2e/last-run.png"))
    }

    @Test
    fun `signs in and reaches the order history`() {
        device.findObject(By.text("Sign in")).waitForExists(10_000).click()

        val order = device.findObject(By.text("Order #1234"))
        assertTrue(order.waitForExists(10_000))
    }
}

class TokenService(private val clock: Clock, private val random: Random) {

    fun issue(): Session {
        val token = buildString { repeat(32) { append(random.nextInt(16).toString(16)) } }
        return Session(token, clock.now() + 30.minutes)
    }
}

class TokenServiceTest {

    private val fixedClock = object : Clock {
        override fun now(): Instant = Instant.parse("2026-08-13T12:00:00Z")
    }

    @Test
    fun `expiry is relative to the injected clock`() {
        val service = TokenService(fixedClock, Random(42))

        assertEquals("2026-08-13T12:30:00Z", service.issue().expiresAt.toString())
    }

    @Test
    fun `a fixed seed produces a reproducible token`() {
        val a = TokenService(fixedClock, Random(7)).issue().token
        val b = TokenService(fixedClock, Random(7)).issue().token

        assertEquals(a, b)
    }
}

